 function score(quality,level){return Math.round(clamp(quality,0,100)*(.50+.50*clamp(level,1,8)/8));}
 function summarize(state,id){const rows=records(state,id).filter(x=>x.protocol!=='scenario'), bench=rows.filter(x=>x.protocol==='benchmark');if(!rows.length)return null;const recent=rows.slice(-5),weights=recent.map((_,i)=>i+1);const value=Math.round(recent.reduce((a,s,i)=>a+s.score*weights[i],0)/weights.reduce((a,b)=>a+b,0));return {value,baseline:rows[0].score,delta:value-rows[0].score,count:rows.length,level:rows.at(-1).nextLevel||3,last:rows.at(-1),benchmark:bench.length?bench.at(-1).score:null};}
 function nextLevel(level,quality){return clamp(level+(quality>=85?1:quality<50?-1:0),1,8);}
