 function wilson(success,total){if(!total)return [0,100];const z=1.96,p=success/total,d=1+z*z/total,c=(p+z*z/(2*total))/d,m=z*Math.sqrt(p*(1-p)/total+z*z/(4*total*total))/d;return [Math.max(0,Math.round((c-m)*100)),Math.min(100,Math.round((c+m)*100))];}
 function validSession(x){return x&&legacySkills.includes(x.skill)&&/^(cs2|valorant):(mouse|touch):(?:(?:standard|trackpad):focus4|(?:direct|look)(?::world3d1|:(?:world3d[2345]|round3d1|range2d1|round2d1|fpsnative1|roundfps1):[a-z0-9-]+)?)$/.test(x.context)&&Number.isFinite(x.at)&&x.at>0&&x.at<Date.now()+86400000&&Number.isFinite(x.score)&&x.score>=0&&x.score<=100&&Number.isFinite(x.quality)&&x.quality>=0&&x.quality<=100&&Number.isInteger(x.level)&&x.level>=1&&x.level<=8&&Number.isFinite(x.duration)&&x.duration>0&&x.duration<7200&&Number.isInteger(x.trials)&&x.trials>=0&&Number.isInteger(x.success)&&x.success>=0&&x.success<=x.trials;}
 function validate(data){if(!data||data.version!==VERSION||!Array.isArray(data.sessions)||data.sessions.length>20000||!data.sessions.every(validSession))throw Error('This is not a valid Stratum v3 backup. No data was changed.');const d=defaults(),s=data.settings||{};for(const k of ['game','input','interaction','theme','crossStyle','density','corners','device','triggerMode']){const allow={device:['mouse','trackpad','touch'],triggerMode:['tap','auto'],game:['cs2','valorant'],input:['auto','mouse','touch'],interaction:['direct','look'],theme:['dark','light'],density:['comfortable','compact'],corners:['soft','square'],crossStyle:['cross','dot','circle']};if(allow[k].includes(s[k]))d.settings[k]=s[k];}for(const k of ['accent','crosshair'])if(/^#[0-9a-f]{6}$/i.test(s[k]||''))d.settings[k]=s[k];for(const k of ['crossSize','crossGap','crossWidth','sensitivity','duration','fov','hudScale','weaponMotion']){const ranges={crossSize:[2,28],crossGap:[0,12],crossWidth:[1,5],sensitivity:[.2,3],duration:[20,60],fov:[50,85],hudScale:[.8,1.3],weaponMotion:[0,1]};if(Number.isFinite(s[k]))d.settings[k]=clamp(s[k],...ranges[k]);}d.settings.sound=s.sound===true;d.settings.reduced=s.reduced===true;for(const game of ['cs2','valorant'])if(new RegExp('^'+game+'-[a-z0-9-]+$').test(s.loadout?.[game]||''))d.settings.loadout[game]=s.loadout[game];for(const game of ['cs2','valorant'])d.settings.rank[game]=String(s.rank?.[game]||'').slice(0,50);d.sessions=data.sessions;d.matches=Array.isArray(data.matches)?data.matches.filter(x=>x&&['cs2','valorant'].includes(x.game)&&Number.isFinite(x.at)&&Number.isFinite(x.rating)&&x.rating>=0&&x.rating<=50000&&['win','loss','draw'].includes(x.result)).slice(-500):[];return d;}
 const api={VERSION,skills,quality,clamp,defaults,inputMode,context,records,score,summarize,nextLevel,priorities,recommendation,overall,tier,wilson,validate,validSession};
